import{_ as o,o as i,c as t,a5 as l}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"Vue 的 Diff 算法简介","description":"Vue 的 Diff 算法简介 Vue.js 的 diff 算法用于比较两个虚拟 DOM 树，并确定如何高效地将变化应用到实际的 DOM 上。diff 算法是 Vue 性能优化的关键之一，因为它通过最小化 DOM 操作来提升渲染性能。 Vue 2 的 Diff 算法 Vue 2。","frontmatter":{"title":"Vue 的 Diff 算法简介","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","原理与手写实现"],"description":"Vue 的 Diff 算法简介 Vue.js 的 diff 算法用于比较两个虚拟 DOM 树，并确定如何高效地将变化应用到实际的 DOM 上。diff 算法是 Vue 性能优化的关键之一，因为它通过最小化 DOM 操作来提升渲染性能。 Vue 2 的 Diff 算法 Vue 2。","sidebarWeight":14,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/原理/Vue 的 Diff 算法简介.md"},"headers":[],"relativePath":"posts/Vue系统教程/05-原理与手写实现/Vue 的 Diff 算法简介.md","filePath":"posts/Vue系统教程/05-原理与手写实现/Vue 的 Diff 算法简介.md"}'),r={name:"posts/Vue系统教程/05-原理与手写实现/Vue 的 Diff 算法简介.md"};function a(f,e,s,n,d,u){return i(),t("div",null,[...e[0]||(e[0]=[l('<div><h1 id="vue-的-diff-算法简介" tabindex="-1">Vue 的 Diff 算法简介 <a class="header-anchor" href="#vue-的-diff-算法简介" aria-label="Permalink to &quot;Vue 的 Diff 算法简介&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue 的 Diff 算法简介”的核心思路，并能把它用于实际开发或面试表达。 Vue 的 Diff 算法简介 Vue.js 的 diff 算法用于比较两个虚拟 DOM 树，并确定如何高效地将变化应用到实际的 DOM 上。diff 算法是 Vue 性能优化的关键之一，因为它通过最小化 DOM 操作来提升渲染性能。</p></blockquote><p>Vue 2 的 Diff 算法 Vue 2 使用的是基于 <a href="https://github.com/snabbdom/snabbdom" target="_blank" rel="noreferrer">snabbdom</a> 的 diff 算法。这个算法的主要特性包括：</p><ol><li><strong>逐层比较</strong>：</li></ol><ul><li>从根节点开始，对新旧虚拟 DOM 树的每一层进行比较。 2. <strong>同层比较</strong>：</li><li>只比较同一层级的节点，不会跨层比较。 3. <strong>四种节点操作</strong>：</li><li><strong>创建新节点</strong>：在新虚拟 DOM 树中存在而旧虚拟 DOM 树中不存在的节点。</li><li><strong>删除旧节点</strong>：在旧虚拟 DOM 树中存在而新虚拟 DOM 树中不存在的节点。</li><li><strong>更新节点</strong>：新旧虚拟 DOM 树中都存在的节点，但属性或子节点不同。</li><li><strong>移动节点</strong>：同一层级的节点顺序发生变化时，需要移动节点。</li></ul><ol start="4"><li><strong>通过 key 进行优化</strong>：</li></ol><ul><li>在列表渲染中使用 <code>key</code> 属性来标识节点，避免不必要的重新渲染和移动操作。</li></ul><p>示例： const oldVNode = h(&#39;div&#39;, [ h(&#39;p&#39;, &#39;Old Paragraph 1&#39;), h(&#39;p&#39;, &#39;Old Paragraph 2&#39;) ]); const newVNode = h(&#39;div&#39;, [ h(&#39;p&#39;, &#39;New Paragraph 1&#39;), h(&#39;p&#39;, &#39;Old Paragraph 2&#39;) ]); // Vue 会通过 diff 算法比较 oldVNode 和 newVNode，并更新实际 DOM。</p><p>Vue 3 的 Diff 算法 Vue 3 对 diff 算法进行了优化，以提高性能和减少内存消耗。主要的改进包括：</p><ol><li><strong>静态提升</strong>：</li></ol><ul><li>Vue 3 会在编译阶段识别出静态节点，并在渲染过程中跳过这些节点的比较和更新。</li></ul><ol start="2"><li><strong>块级优化</strong>：</li></ol><ul><li>使用“块”来分割虚拟 DOM 树，将相同类型的节点分组，减少比较的复杂度。</li></ul><ol start="3"><li><strong>Fragment 支持</strong>：</li></ol><ul><li>支持多个根节点（Fragment），使得 diff 算法可以处理更复杂的场景。</li></ul><ol start="4"><li><strong>更智能的列表对比</strong>：</li></ol><ul><li>改进了列表对比算法，使用双端比较技术（双指针）来优化节点移动的性能。</li></ul><h4 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h4><p>const oldVNode = h(&#39;div&#39;, [ h(&#39;p&#39;, { key: 1 }, &#39;Old Paragraph 1&#39;), h(&#39;p&#39;, { key: 2 }, &#39;Old Paragraph 2&#39;) ]); const newVNode = h(&#39;div&#39;, [ h(&#39;p&#39;, { key: 1 }, &#39;New Paragraph 1&#39;), h(&#39;p&#39;, { key: 2 }, &#39;Old Paragraph 2&#39;) ]); // Vue 3 会通过更高效的 diff 算法比较 oldVNode 和 newVNode，并更新实际 DOM。</p><p>总结</p><ul><li><strong>Vue 2</strong>：使用的是基于 snabbdom 的 diff 算法，通过逐层和同层比较，并结合 <code>key</code> 属性优化列表渲染。</li><li><strong>Vue 3</strong>：对 diff 算法进行了多项改进，如静态提升、块级优化、Fragment 支持和更智能的列表对比，使其性能和内存消耗更优。 这些优化使得 Vue 3 在处理复杂场景和大型应用时，能够提供更高的性能和更好的用户体验。</li></ul></div>',1)])])}const p=o(r,[["render",a]]);export{g as __pageData,p as default};
